<?php $title='Configuração da propriedade';require __DIR__.'/_top.php';?><div class="page-heading"><div><p class="eyebrow">Base operacional</p><h1>Propriedade e políticas</h1></div></div>
<?php if($contractMissing):?><div class="admin-alert error"><strong>Contrato bloqueado.</strong> Campos pendentes: <?= e(implode(', ',$contractMissing)) ?>.</div><?php endif;?><?php if(!$pricingReadiness['ready']):?><div class="admin-alert error"><strong>Preço público bloqueado.</strong> <?= e(implode(', ',$pricingReadiness['missing'])) ?></div><?php endif;?>
<form class="admin-panel admin-form" action="<?= e(base_url('admin/operacoes/property-update')) ?>" method="post"><?= csrf_field() ?><div class="settings-grid"><?php foreach($settings as $key=>$setting):$type=$setting['type']??'string';$value=$setting['value']??null;?><label><span><?= e($key) ?> <?= !empty($setting['required'])?'*':'' ?></span><?php if($type==='boolean'):?><input type="hidden" name="<?= e($key) ?>" value="0"><input type="checkbox" name="<?= e($key) ?>" value="1" <?= $value?'checked':'' ?>><?php elseif($type==='time'):?><input type="time" name="<?= e($key) ?>" value="<?= e($value) ?>"><?php elseif(in_array($type,['integer','money'],true)):?><input type="number" min="0" step="<?= $type==='money'?'0.01':'1' ?>" name="<?= e($key) ?>" value="<?= e($value) ?>"><?php else:?><textarea name="<?= e($key) ?>" rows="<?= in_array($key,['CANCELLATION_POLICY','ARRIVAL_DIRECTIONS','ACCESS_INSTRUCTIONS'],true)?4:2 ?>"><?= e($value) ?></textarea><?php endif;?><small><?= !empty($setting['configured'])?'Configurado':'Pendente' ?></small></label><?php endforeach;?></div><button class="admin-primary">Salvar configurações</button></form><?php require __DIR__.'/_bottom.php';?>
